(()=>{function clean(){document.querySelectorAll('.product-info>.eyebrow').forEach(el=>el.remove());document.querySelectorAll('.product-card .type').forEach(el=>el.remove());document.querySelectorAll('.product-info .detail-type').forEach(el=>{const t=el.textContent.trim();const m=t.match(/(\d+(?:\.\d+)?\s*(?:ml|مل|g|kg|gm|جرام|غرام|قطعة|pcs?))/i);if(m)el.textContent=m[1].replace(/\s+/g,' ');else{const parts=t.split('·').map(x=>x.trim()).filter(Boolean);if(parts.length>1)el.textContent=parts[parts.length-1]}})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',clean);else clean();window.addEventListener('load',clean);setTimeout(clean,300);setTimeout(clean,1200);})();